function sortJSONObjectByKeys(jsonObj) {
  const obj = JSON.parse(jsonObj); // Convert JSON string to JavaScript object
  const keys = Object.keys(obj).sort(); // Sort keys
  const result = {}; // Initialize empty object to store sorted data

  for (let I = 0; I < keys.length; i++) {
    result[keys[i]] = obj[keys[i]]; // Copy values from original object to sorted object
  }

  return JSON.stringify(result); // Convert sorted JavaScript object back to JSON string
}
```

Here's how you can use this function:

```js
const jsonStr = '{"name": "John", "age": 30, "city": "New York"}'
const sortedJsonStr = sortJSONObjectByKeys(jsonStr)
console.log(sortedJsonStr)
// Output: {"age": 30, "city": "New York", "name": "John"}
```

In case you want to sort the JSON object by some custom comparison function, you can modify the `sort()` method inside the `sortJSONObjectByKeys()` function accordingly.

