 function morseCode = encodeMorse(input)
   % Convert input string to uppercase and replace spaces with dot-dash separator
   input = strrep(strupper(input), ' ', '.- ');

   % Define Morse Code dictionary
   morseDict = {'. ', '-...', '-.-.', '-.. ', '. ', '..- ', '--.', '.... ', '. ', '..- ', '.-- ', '--.', '-. ', '.-.. ', '-- ', '-.');

   % Initialize output string
   morseCode = '';

   % Iterate over each character in input and add its corresponding Morse Code sequence to output
   for I = 1:length(input)
     morseCode = [morseCode; morseDict{input(i)}];
   end
 end
 ```

