Here's a Javascript function that takes a string variable in dot notation and returns all entries in an object where the nested key-value pair matches the given string:

```javascript
function findEntriesInObject(obj, searchKey) {
  let result = {};

  function getValue(key) {
    return obj[key] !== undefined ? obj[key] : null;
  }

  function traverseObject(obj) {
    for (let key in obj) {
      const val = getValue(key);

      if (val !== null && typeof val === 'object') {
        const subResult = traverseObject(val);
        Object.assign(result, subResult);
      } else if (val !== null && key.split('.').length > searchKey.split('.').length) {
        // If the current key is deeper than the search key, stop traversing
        continue;
      } else if (val !== null && key.split('.').slice(-1)[0] === searchKey.split('.').slice(-1)[0]) {
        // If the last part of the current key matches the search key, add it to the result
        const lastIndex = key.lastIndexOf('.');
        result[key.substring(lastIndex + 1)] = val;
      }
    }

    return result;
  }

  return traverseObject(obj);
}
```

To use this function, pass in your object and the dot-notated key you want to search for, like so:

```javascript
const myObj = {
  a: { b: 123 },
  c: { d: { e: 'foo', f: 'bar' } },
};
const result = findEntriesInObject(myObj, 'f');
console.log(result); // Output: { f: 'bar' }
```

The function uses recursion to traverse the object tree and check each key-value pair against the search key. It also keeps track of the deepest level it has traversed, so it can stop checking once it reaches a point where the search key cannot be found.

