```jsx
import React, { useState } from 'react';
import './App.css';

function App() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('c'); // Celsius is the default unit
  const [result, setResult] = useState(null);

  const handleInputChange = e => {
    setTemperature(e.target.value);
  };

  const handleUnitChange = e => {
    setUnit(e.target.value);
    convert();
  };

  const convert = () => {
    switch (unit) {
      case 'c':
        return setResult((temperature * 9) / 5 + 32); // Convert Celsius to Fahrenheit
      case 'f':
        return setResult((temperature - 32) * 5 / 9); // Convert Fahrenheit to Celsius
      default:
        return null;
    }
  };

  return (
    <div className="App">
      <h1>{result !== null ? `${Math.round(result)} ${unit === 'c' ? '°C' : '°F'}` : ''}</h1>
      <label htmlFor="temperature-input">Enter Temperature:</label>
      <input type="number" id="temperature-input" value={temperature} onChange={handleInputChange} />
      <label htmlFor="unit-select">Select Unit:</label>
      <select id="unit-select" value={unit} onChange={handleUnitChange}>
        <option value="c">Celsius</option>
        <option value="f">Fahrenheit</option>
      </select>
    </div>
  );
}

export default App;
```

