```powershell
Install-Package Accord.NET
```

Next, let's create a console application and write the following code:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Accord.Statistics.Models.NaiveBayes;
using Accord.Text;
using Accord.WkiCSV;

namespace TextClassificationApp
{
    class Program
    {
        static void Main(string[] args)
        {
            string dataPath = @"C:\path\to\your\data.csv";
            string[] categories = { "Sports", "Politics", "Entertainment" };

            var dataset = WkiCSVReader.ReadCSV<string[]>(dataPath);
            var featureExtractor = new CountVectorizer(true);
            var labels = dataset.Select(x => categories[Array.IndexOf(categories, x[0])]).ToArray();
            var trainingSet = featureExtractor.Transform(dataset.Skip(1).Take(500));
            var testSet = featureExtractor.Transform(new[] { dataset[501], dataset[502] });

            var naiveBayes = new NaiveBayesClassifier<double>();
            naiveBayes.Fit(trainingSet, labels);

            Console.WriteLine("Prediction:");
            double[] prediction = naiveBayes.Transform(testSet[0]);
            Console.WriteLine($"{categories[Array.IndexOf(labels, naiveBayes.LabelWithMaxScore(prediction))]} ({naiveBayes.GetProbability(prediction, categories[0]) * 100:F2})%");

            Console.ReadLine();
        }
    }
}
```

