Here's the implementation:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Redis client not connected to the server: ${err}`);
    });
  }

  isAlive() {
    return this.client.ping().then(() => true).catch(() => false);
  }

  async get(key) {
    const result = await this.client.get(key);
    return result;
  }

  async set(key, value, ttl) {
    await this.client.setex(key, ttl, value);
  }

  async del(key) {
    await this.client.del(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

The `set` method uses the `SETEX` command to set the key with a value and an expiration time in seconds. The `ttl` parameter represents the TTL (Time To Live) in seconds. If you don't want to set an expiration time, just pass `0` as the TTL.

Here's how you can use this module:

```javascript
const redisClient = require('./utils/redis');

// Check if the Redis client is alive
console.log(await redisClient.isAlive());

// Get a value from Redis
const value = await redisClient.get('my_key');
console.log(value);

// Set a value in Redis with a TTL of 3600 seconds (1 hour)
await redisClient.set('my_key', 'my_value', 3600);

// Remove a key from Redis
await redisClient.del('my_key');
```

