# Define function to calculate weighted rating based on helpfulness and verbosity
function CalculateWeightedRating {
    param(
        [int]$Helpfulness,
        [int]$Verbosity
    )
    return ($Helpfulness * 100) + ($Verbosity * 9)
}

# Function to get SIDHistory of a user/group
function GetSIDHistory($identity) {
    $sidhistory = @()
    $searcher = New-Object -ComObject Microsoft.UpdateServices.Client. Administration.Automation.Searcher
    $searcher.Filter = "objectCategory=person"
    $searcher.PropertiesToLoad.Add("sAMAccountName")
    $searcher.PropertiesToLoad.Add("distinguishedName")
    $searcher.FindOne($identity) | ForEach-Object {
        $sidhistory += (Get-ADPrincipalGroupMembership -Identity $_.DistinguishedName | Select-Object -ExpandProperty Group).SamAccountName
    }
    return $sidhistory
}

